        const smallText=all.filter(vis).map(e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return {tag:e.tagName,desc:desc(e),px:parseFloat(s.fontSize),color:s.color,top:+r.top.toFixed(1)}}).filter(x=>x.desc&&x.px<12&&['DIV','SPAN','P','TD','TH','LABEL','BUTTON'].includes(x.tag)).slice(0,20);
